<?php if($role==='customer'): ?><section class="panel narrow"><h2>Submit a concern</h2><form action="<?= site_url('support') ?>" method="post"><?= csrf_field() ?><label>Subject<input name="subject" maxlength="150" required></label><label>How can we help?<textarea name="message" minlength="10" maxlength="5000" rows="5" required></textarea></label><button type="submit">Submit concern</button></form></section><?php endif ?>
<section class="panel"><h2><?= $role==='admin'?'Customer concerns':'Your concerns' ?></h2><?php if(!$tickets): ?><p>No support concerns to show.</p><?php endif ?><?php foreach($tickets as $ticket): ?><article class="notice"><span class="badge"><?= esc($ticket['status']) ?></span><h3>#<?= (int)$ticket['id'] ?> · <?= esc($ticket['subject']) ?></h3><p class="pre-line"><?= esc($ticket['message']) ?></p><?php if($ticket['response']): ?><h4>Company response</h4><p class="pre-line"><?= esc($ticket['response']) ?></p><?php endif ?><?php if($role==='admin'): ?><form action="<?= site_url('support/'.$ticket['id'].'/respond') ?>" method="post"><?= csrf_field() ?><label>Response<textarea name="response" minlength="2" maxlength="5000" required><?= esc($ticket['response']??'') ?></textarea></label><label>Status<select name="status"><option value="open">Open</option><option value="resolved" <?= $ticket['status']==='resolved'?'selected':'' ?>>Resolved</option></select></label><button type="submit">Save response</button></form><?php endif ?></article><?php endforeach ?></section>
